#!/usr/bin/env python3
import os, json, math, sys

# Physical constants (SI)
G = 6.67430e-11            # m^3 kg^-1 s^-2
c = 2.99792458e8          # m s^-1
M_sun = 1.98847e30        # kg

# Helper to load a GWTC catalog via environment variable
def load_gwtc_catalog():
    path = os.getenv('GWTC_CATALOG_PATH')
    if path and os.path.isfile(path):
        try:
            with open(path, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Failed to load catalog: {e}")
    # Small synthetic fallback – may be insufficient for real analysis
    return {
        "events": [
            {"mass_1_source": 30.0, "mass_2_source": 35.0, "final_mass_source": 62.0},
            {"mass_1_source": 15.0, "mass_2_source": 20.0, "final_mass_source": 33.0}
        ]
    }

def compute_radiated_fraction(event):
    m1 = event.get("mass_1_source")
    m2 = event.get("mass_2_source")
    mf = event.get("final_mass_source")
    if None in (m1, m2, mf):
        return None
    total_initial = m1 + m2
    # Guard against negative or zero initial mass
    if total_initial <= 0:
        return None
    radiated = (total_initial - mf) / total_initial
    return radiated

def main():
    catalog = load_gwtc_catalog()
    events = catalog.get("events", [])
    fractions = []
    for ev in events:
        eps = compute_radiated_fraction(ev)
        if eps is not None:
            fractions.append(eps)
    if not fractions:
        print("No valid events found.")
        sys.exit(0)
    fractions = sorted(fractions)
    median = fractions[len(fractions)//2]
    threshold = 0.05  # 5% radiated as a conservative bound
    result = "PASS" if median <= threshold else "FAIL"
    print(f"Median radiated fraction: {median:.4f}")
    print(f"Result: {result}")

if __name__ == "__main__":
    main()

