import os, json, math, numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8         # m·s⁻¹
M_sun = 1.98847e30       # kg
hbar = 1.054571817e-34   # J·s
k_B = 1.380649e-23       # J·K⁻¹


def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M):
    # prograde ISCO radius (meters) for a non-rotating BH
    return 6 * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def photon_sphere_radius(M):
    return 3 * G * M / c**2

def critical_impact_parameter(M):
    # b_crit = 3*sqrt(3) * GM / c^2
    return 3 * math.sqrt(3) * G * M / c**2

def angular_velocity_isco(M):
    # Ω_ISCO = 1 / (3^(3/2) - 1) * c^3 / (GM)
    return c**3 / ((3**1.5 - 1) * G * M)

def angular_velocity_photon_sphere(M):
    # Ω_ph = c^3 / (3*sqrt(3) * GM)
    return c**3 / (3 * math.sqrt(3) * G * M)

def critical_impact_parameter_angle(M):
    # tan(b_crit/r) = sqrt(3) / 3  =>  b_crit = r * sqrt(3)/3
    return (3 * math.sqrt(3) * G * M / c**2) * (1 / 3)

def critical_impact_parameter_rad(M):
    # b_crit = 3*sqrt(3) * GM / c^2
    return 3 * math.sqrt(3) * G * M / c**2

def critical_impact_parameter_deg(M):
    rad = critical_impact_parameter_rad(M)
    return math.degrees(rad)

def critical_impact_parameter_mas(M):
    rad = critical_impact_parameter_rad(M)
    # 1 mas = 1e-3 arcsec
    return rad * 1e3

def critical_impact_parameter_microarcsec(M):
    rad = critical_impact_parameter_rad(M)
    return rad * 1e6

def critical_impact_parameter_microsecond(M):
    # b_crit * c / (1e-6)  (convert seconds to microseconds)
    return critical_impact_parameter_rad(M) * c * 1e6

def critical_impact_parameter_year(M):
    return critical_impact_parameter_rad(M) * c * 365.25 * 24 * 3600

def critical_impact_parameter_lightcurve(M):
    # For a continuous GW source the dimensionless critical impact parameter
    # (b_crit / (v*t)) = (3*sqrt(3)/c) * (GM / (v*t))
    # Using v = c and t = 1 yr
    return (3 * math.sqrt(3) / c) * (G * M / (c * 365.25 * 24 * 3600))

def main():
    # Example: 10 solar‑mass black hole
    M = 10 * M_sun
    print(f"Schwarzschild radius (r_s) for M = {M:.2e} kg: {schwarzschild_radius(M):.3e} m")
    print(f"ISCO radius (r_isco) for a non‑rotating BH: {isco_radius(M):.3e} m")
    print(f"Hawking temperature: {hawking_temperature(M):.3e} K")
    print(f"Planck length: {planck_length():.3e} m")
    print(f"Photon‑sphere radius: {photon_sphere_radius(M):.3e} m")
    print(f"Critical impact parameter (b_crit): {critical_impact_parameter(M):.3e} m ({critical_impact_parameter_deg(M):.2f} deg)")
    print(f"Critical impact parameter in mas: {critical_impact_parameter_mas(M):.3e} mas")
    print(f"Critical impact parameter in microseconds: {critical_impact_parameter_microsecond(M):.3e} µs")
    print(f"Critical impact parameter in years: {critical_impact_parameter_year(M):.3e} yr")
    print(f"Dimensionless critical impact parameter (b_crit/(v*t)): {critical_impact_parameter_lightcurve(M):.3e}")

if __name__ == "__main__":
    main()
